steps.script:
function transform(ctx) {
  var u = ctx.vars.portal_url || "";
  if (!u || u.indexOf("?") < 0) throw new Error("未能获取门户跳转地址（Location），请核对本校门户地址后把地址写进本步骤脚本");
  var q = u.slice(u.indexOf("?") + 1);
  var host = u.split("/")[2];
  var service = ""; // 原实现 core/wifi.py login_wifi: service 固定传空，与运营商无关
  return { portal_host: host, qse: url_encode(q), eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), es: url_encode(service) };
}
